use kimo_core::{commands::{Session,dispatch},model::{Source,Effect},render};use serde_json::json;
fn scene()->(Session,String){let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":16,"height":16,"fps":25})).unwrap();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":3}})).unwrap();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let id=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","color":[0.8,0.2,0.05],"start":0,"duration":1})).unwrap()["clip_id"].as_str().unwrap().to_string();dispatch(&mut s,"add_managed_linear_effect",&json!({"clip_id":id,"kind":"linear_grade","params":{"exposure":4,"offset":-0.5}})).unwrap();(s,id)}
#[test]fn grouping_no_second_decode(){let(mut s,id)=scene();let a=render::render_frame(&s.project,0.5,&s.cache).unwrap();let g=dispatch(&mut s,"group_clips",&json!({"clip_ids":[id]})).unwrap();let b=render::render_frame(&s.project,0.5,&s.cache).unwrap();assert_eq!(a.d,b.d);assert!(a.d.iter().any(|v|*v>1.));assert!(a.d.iter().any(|v|*v<0.));let _=g;}
#[test]fn precomp_render_error_not_black_success(){let(mut s,id)=scene();let g=dispatch(&mut s,"group_clips",&json!({"clip_ids":[id]})).unwrap()["clip_id"].as_str().unwrap().to_string();if let Source::Precomp{tracks}=&mut s.project.find_clip_mut(&g).unwrap().source{tracks[0].clips[0].effects.push(Effect{id:"bad".into(),kind:"linear_grade".into(),params:[("exposure".into(),kimo_core::keyframe::Prop::new(1e8))].into_iter().collect(),strings:Default::default()});}assert!(render::render_frame(&s.project,0.5,&s.cache).is_err());}
